window.docContents[255].resolve({"/Lists/#Logical-Foundations--Lists___-Working-with-Structured-Data--Lists-of-Numbers--Type-Classes-and-Overloading--Exercises":{"contents":"\n\nComplete the definitions of nonZeros, oddMembers, and\ncountOddMembers below. Have a look at the lemmas and examples to understand\nwhat these functions should do.def nonZeros (l : NatList) : NatList := solution!(\n  match l with\n  | [] => []\n  | 0 :: t => nonZeros t\n  | h :: t => h :: nonZeros t\n)\ndef nonZeros (l : NatList) : NatList := sorry\ndef nonZeros (l : NatList) : NatList := sorry\nThe following lemmas should hold about your definitiontheorem nonZeros_cons_zero {t : NatList} :\n    nonZeros (0 :: t) = nonZeros t := solution!(by rfl)\n\ntheorem nonZeros_nil :\n    nonZeros [] = [] := solution!(by rfl)\n\ntheorem nonZeros_cons_nonZero {h : Nat} {t : NatList} :\n    nonZeros ((h + 1) :: t) = (h + 1) :: nonZeros t := solution!(by rfl)\n\ntheorem test_nonZeros : nonZeros [0, 1, 0] = [1] := by\n  solution!\n    rw [nonZeros_cons_zero]\n    rw [nonZeros_cons_nonZero]\n    rw [nonZeros_cons_zero]\n    rw [nonZeros_nil]\ntheorem nonZeros_cons_zero {t : NatList} :\n    nonZeros (0 :: t) = nonZeros t := sorry\n\ntheorem nonZeros_nil :\n    nonZeros [] = [] := sorry\n\ntheorem nonZeros_cons_nonZero {h : Nat} {t : NatList} :\n    nonZeros ((h + 1) :: t) = (h + 1) :: nonZeros t := sorry\n\ntheorem test_nonZeros : nonZeros [0, 1, 0] = [1] := by\n  sorry\ntheorem nonZeros_cons_zero {t : NatList} :\n    nonZeros (0 :: t) = nonZeros t := sorry\n\ntheorem nonZeros_nil :\n    nonZeros [] = [] := sorry\n\ntheorem nonZeros_cons_nonZero {h : Nat} {t : NatList} :\n    nonZeros ((h + 1) :: t) = (h + 1) :: nonZeros t := sorry\n\ntheorem test_nonZeros : nonZeros [0, 1, 0] = [1] := by\n  sorry\ndef oddMembers (l : NatList) : NatList := solution!(\n  match l with\n  | [] => []\n  | h :: t => bif h.odd then h :: oddMembers t else oddMembers t)\n\ntheorem oddMembers_nil :\n    oddMembers [] = [] := solution!(by rfl)\n\ntheorem oddMembers_cons {h : Nat} {t : NatList} :\n    oddMembers (h :: t) =\n      bif h.odd then h :: oddMembers t else oddMembers t :=\n  solution!(by rfl)\n\ntheorem oddMembers_cons_odd {x : Nat} {l : NatList}\n    (h : x.odd = true) :\n    oddMembers (x :: l) = x :: oddMembers l := by\n  solution!\n    rw [oddMembers_cons, h, cond_true]\n\ntheorem oddMembers_cons_not_odd {x : Nat} {l : NatList}\n    (h : x.odd = false) :\n    oddMembers (x :: l) = oddMembers l := by\n  solution!\n    rw [oddMembers_cons, h, cond_false]\ndef oddMembers (l : NatList) : NatList := sorry\n\ntheorem oddMembers_nil :\n    oddMembers [] = [] := sorry\n\ntheorem oddMembers_cons {h : Nat} {t : NatList} :\n    oddMembers (h :: t) =\n      bif h.odd then h :: oddMembers t else oddMembers t :=\n  sorry\n\ntheorem oddMembers_cons_odd {x : Nat} {l : NatList}\n    (h : x.odd = true) :\n    oddMembers (x :: l) = x :: oddMembers l := by\n  sorry\n\ntheorem oddMembers_cons_not_odd {x : Nat} {l : NatList}\n    (h : x.odd = false) :\n    oddMembers (x :: l) = oddMembers l := by\n  sorry\ndef oddMembers (l : NatList) : NatList := sorry\n\ntheorem oddMembers_nil :\n    oddMembers [] = [] := sorry\n\ntheorem oddMembers_cons {h : Nat} {t : NatList} :\n    oddMembers (h :: t) =\n      bif h.odd then h :: oddMembers t else oddMembers t :=\n  sorry\n\ntheorem oddMembers_cons_odd {x : Nat} {l : NatList}\n    (h : x.odd = true) :\n    oddMembers (x :: l) = x :: oddMembers l := by\n  sorry\n\ntheorem oddMembers_cons_not_odd {x : Nat} {l : NatList}\n    (h : x.odd = false) :\n    oddMembers (x :: l) = oddMembers l := by\n  sorry\nNow, we can prove that oddMembers [1, 2] returns [1] using the lemmas:example : oddMembers [1, 2] = [1] := by\n  rw [oddMembers_cons_odd]\n  · rw [oddMembers_cons_not_odd]\n    · rw [oddMembers_nil]\n    · rw [Nat.odd_def]\n      rw [even_succ, even_succ, even_zero, Bool.not_true, Bool.not_false, Bool.not_true]\n  · rw [Nat.odd, even_succ, even_zero, Bool.not_true, Bool.not_false]\nexample : oddMembers [1, 2] = [1] := by\n  rw [oddMembers_cons_odd]\n  · rw [oddMembers_cons_not_odd]\n    · rw [oddMembers_nil]\n    · rw [Nat.odd_def]\n      rw [even_succ, even_succ, even_zero, Bool.not_true, Bool.not_false, Bool.not_true]\n  · rw [Nat.odd, even_succ, even_zero, Bool.not_true, Bool.not_false]\nexample : oddMembers [1, 2] = [1] := by\n  rw [oddMembers_cons_odd]\n  · rw [oddMembers_cons_not_odd]\n    · rw [oddMembers_nil]\n    · rw [Nat.odd_def]\n      rw [even_succ, even_succ, even_zero, Bool.not_true, Bool.not_false, Bool.not_true]\n  · rw [Nat.odd, even_succ, even_zero, Bool.not_true, Bool.not_false]\nThis gets pretty verbose quite fast, however we can use rfl to deal with subgoals such as Nat.odd 2 = false:example : oddMembers [1, 2] = [1] := by\n  rw [oddMembers_cons_odd]\n  · rw [oddMembers_cons_not_odd]\n    · rw [oddMembers_nil]\n    · rfl\n  · rfl\nexample : oddMembers [1, 2] = [1] := by\n  rw [oddMembers_cons_odd]\n  · rw [oddMembers_cons_not_odd]\n    · rw [oddMembers_nil]\n    · rfl\n  · rfl\nexample : oddMembers [1, 2] = [1] := by\n  rw [oddMembers_cons_odd]\n  · rw [oddMembers_cons_not_odd]\n    · rw [oddMembers_nil]\n    · rfl\n  · rfl\nIn fact, as the entire proof is just plain computation, it can be done with a single rfl.\nThis is possible because all of the elements and lists are concrete -- there are no variables involved.example : oddMembers [1, 2] = [1] := solution!(by rfl)\n\ntheorem test_oddMembers : oddMembers [0, 1, 2, 3, 0] = [1, 3] := solution!(by rfl)\nexample : oddMembers [1, 2] = [1] := sorry\n\ntheorem test_oddMembers : oddMembers [0, 1, 2, 3, 0] = [1, 3] := sorry\nexample : oddMembers [1, 2] = [1] := sorry\n\ntheorem test_oddMembers : oddMembers [0, 1, 2, 3, 0] = [1, 3] := sorry\nFor the next problem, countOddMembers, we encourage you to implement it using\nalready-defined functions, rather than recursion.def countOddMembers (l : NatList) : Nat := solution!(\n  (oddMembers l).length)\n\ntheorem countOddMembers_def (l : NatList) :\n    countOddMembers l = (oddMembers l).length := solution!(by rfl)\n\nexample : countOddMembers [0, 1, 2, 3, 0] = 2 := by\n  rw [countOddMembers_def]\n  rw [test_oddMembers]\n  rw [length_cons, length_cons, length_nil]\n\nexample : countOddMembers [0, 1, 2, 3, 0] = 2 := solution!(by rfl)\n\ntheorem test_countOddMembers1 : countOddMembers [0, 2, 4] = 0 := solution!(by rfl)\n\ntheorem test_countOddMembers2 : countOddMembers [] = 0 := solution!(by rfl)\ndef countOddMembers (l : NatList) : Nat := sorry\n\ntheorem countOddMembers_def (l : NatList) :\n    countOddMembers l = (oddMembers l).length := sorry\n\nexample : countOddMembers [0, 1, 2, 3, 0] = 2 := by\n  rw [countOddMembers_def]\n  rw [test_oddMembers]\n  rw [length_cons, length_cons, length_nil]\n\nexample : countOddMembers [0, 1, 2, 3, 0] = 2 := sorry\n\ntheorem test_countOddMembers1 : countOddMembers [0, 2, 4] = 0 := sorry\n\ntheorem test_countOddMembers2 : countOddMembers [] = 0 := sorry\ndef countOddMembers (l : NatList) : Nat := sorry\n\ntheorem countOddMembers_def (l : NatList) :\n    countOddMembers l = (oddMembers l).length := sorry\n\nexample : countOddMembers [0, 1, 2, 3, 0] = 2 := by\n  rw [countOddMembers_def]\n  rw [test_oddMembers]\n  rw [length_cons, length_cons, length_nil]\n\nexample : countOddMembers [0, 1, 2, 3, 0] = 2 := sorry\n\ntheorem test_countOddMembers1 : countOddMembers [0, 2, 4] = 0 := sorry\n\ntheorem test_countOddMembers2 : countOddMembers [] = 0 := sorry\nComplete the following definition of alternate, which\ninterleaves two lists into one, alternating between elements taken\nfrom the first list and elements from the second.Hint: there are natural ways of writing alternate that fail to\nsatisfy Lean's requirement that all recursive definitions be\nstructurally recursive, as mentioned in Basics.\nIf you encounter this difficulty,\nconsider pattern matching against both lists at the same time.def alternate (l1 l2 : NatList) : NatList := solution!(\n  match l1, l2 with\n  | [], _ => l2\n  | _, [] => l1\n  | h1 :: t1, h2 :: t2 => h1 :: h2 :: alternate t1 t2)\n\ntheorem test_alternate1 :\n    alternate [1, 2, 3] [4, 5, 6] = [1, 4, 2, 5, 3, 6] := solution!(by rfl)\ndef alternate (l1 l2 : NatList) : NatList := sorry\n\ntheorem test_alternate1 :\n    alternate [1, 2, 3] [4, 5, 6] = [1, 4, 2, 5, 3, 6] := sorry\ndef alternate (l1 l2 : NatList) : NatList := sorry\n\ntheorem test_alternate1 :\n    alternate [1, 2, 3] [4, 5, 6] = [1, 4, 2, 5, 3, 6] := sorry\ntheorem test_alternate2 :\n    alternate [1] [4, 5, 6] = [1, 4, 5, 6] := solution!(by rfl)\ntheorem test_alternate2 :\n    alternate [1] [4, 5, 6] = [1, 4, 5, 6] := sorry\ntheorem test_alternate2 :\n    alternate [1] [4, 5, 6] = [1, 4, 5, 6] := sorry\ntheorem test_alternate3 :\n    alternate [1, 2, 3] [4] = [1, 4, 2, 3] := solution!(by rfl)\n\ntheorem test_alternate4 :\n    alternate [] [20, 30] = [20, 30] := solution!(by rfl)\ntheorem test_alternate3 :\n    alternate [1, 2, 3] [4] = [1, 4, 2, 3] := sorry\n\ntheorem test_alternate4 :\n    alternate [] [20, 30] = [20, 30] := sorry\ntheorem test_alternate3 :\n    alternate [1, 2, 3] [4] = [1, 4, 2, 3] := sorry\n\ntheorem test_alternate4 :\n    alternate [] [20, 30] = [20, 30] := sorry\n\n\n","context":"Logical Foundations\u0009Lists: Working with Structured Data\u0009Lists of Numbers\u0009Type Classes and Overloading","header":"5.2.3.2. Exercises","id":"/Lists/#Logical-Foundations--Lists___-Working-with-Structured-Data--Lists-of-Numbers--Type-Classes-and-Overloading--Exercises"},"/Logic/#Logical-Foundations--Logic-in-Lean--Truth--Logical-Equivalence":{"contents":"The handy \"if and only if\" connective, which asserts that two\npropositions have the same truth value, is a structure containing\nthe two implication directions. P ↔ Q is notation for Iff P Q.\n\n#print Iff\n\n#check (fun α β : Prop => α ↔ β : Prop → Prop → Prop)\n\ntheorem iff_sym (P Q : Prop) (h : P ↔ Q) : (Q ↔ P) := by\n  workinclass!\n    constructor\n    case mp => exact h.mpr\n    case mpr => exact h.mp\n\ntheorem not_true_iff_false (b : Bool) : b ≠ true ↔ b = false := by\n  constructor\n  case mp => apply not_true_is_false\n  case mpr => intro h; rw [h]; intro h'; contradiction\n#print Iff\n\n#check (fun α β : Prop => α ↔ β : Prop → Prop → Prop)\n\ntheorem iff_sym (P Q : Prop) (h : P ↔ Q) : (Q ↔ P) := by\n  all_goals\n    constructor\n    case mp => exact h.mpr\n    case mpr => exact h.mp\n\ntheorem not_true_iff_false (b : Bool) : b ≠ true ↔ b = false := by\n  constructor\n  case mp => apply not_true_is_false\n  case mpr => intro h; rw [h]; intro h'; contradiction\n#print Iff\n\n#check (fun α β : Prop => α ↔ β : Prop → Prop → Prop)\n\ntheorem iff_sym (P Q : Prop) (h : P ↔ Q) : (Q ↔ P) := by\n  sorry\n\ntheorem not_true_iff_false (b : Bool) : b ≠ true ↔ b = false := by\n  constructor\n  case mp => apply not_true_is_false\n  case mpr => intro h; rw [h]; intro h'; contradiction\n\n\nUsing the above proof that ↔ is symmetric (iff_sym) as a guide,\nprove that it is also reflexive and transitive.theorem iff_refl (P : Prop) : P ↔ P := by\n  solution!\n    constructor\n    case mp => intro h; exact h\n    case mpr => intro h; exact h\n\ntheorem iff_trans (P Q R : Prop) (h1 : P ↔ Q) (h2 : Q ↔ R) : (P ↔ R) := by\n  solution!\n    constructor\n    case mp => intro hP; apply h2.mp; apply h1.mp; exact hP\n    case mpr => intro hR; apply h1.mpr; apply h2.mpr; exact hR\ntheorem iff_refl (P : Prop) : P ↔ P := by\n  sorry\n\ntheorem iff_trans (P Q R : Prop) (h1 : P ↔ Q) (h2 : Q ↔ R) : (P ↔ R) := by\n  sorry\ntheorem iff_refl (P : Prop) : P ↔ P := by\n  sorry\n\ntheorem iff_trans (P Q R : Prop) (h1 : P ↔ Q) (h2 : Q ↔ R) : (P ↔ R) := by\n  sorry\n\n\ntheorem or_associate (P Q R : Prop) : P ∨ (Q ∨ R) ↔ (P ∨ Q) ∨ R := by\n  constructor\n  case mp =>\n    intro h\n    obtain hP | (hQ | hR) := h\n    case inl     => left; left; exact hP\n    case inr.inl => left; right; exact hQ\n    case inr.inr => right; exact hR\n  case mpr =>\n    intro h\n    obtain (hP | hQ) | hR := h\n    case inl.inl => left; exact hP\n    case inl.inr => right; left; exact hQ\n    case inr     => right; right; exact hR\ntheorem or_associate (P Q R : Prop) : P ∨ (Q ∨ R) ↔ (P ∨ Q) ∨ R := by\n  constructor\n  case mp =>\n    intro h\n    obtain hP | (hQ | hR) := h\n    case inl     => left; left; exact hP\n    case inr.inl => left; right; exact hQ\n    case inr.inr => right; exact hR\n  case mpr =>\n    intro h\n    obtain (hP | hQ) | hR := h\n    case inl.inl => left; exact hP\n    case inl.inr => right; left; exact hQ\n    case inr     => right; right; exact hR\ntheorem or_associate (P Q R : Prop) : P ∨ (Q ∨ R) ↔ (P ∨ Q) ∨ R := by\n  constructor\n  case mp =>\n    intro h\n    obtain hP | (hQ | hR) := h\n    case inl     => left; left; exact hP\n    case inr.inl => left; right; exact hQ\n    case inr.inr => right; exact hR\n  case mpr =>\n    intro h\n    obtain (hP | hQ) | hR := h\n    case inl.inl => left; exact hP\n    case inl.inr => right; left; exact hQ\n    case inr     => right; right; exact hR\n\n\ntheorem or_distributes_over_and (P Q R : Prop) :\n    P ∨ (Q ∧ R) ↔ (P ∨ Q) ∧ (P ∨ R) := by\n  solution!\n    constructor\n    case mp =>\n      intro h\n      obtain hP | ⟨hQ, hR⟩ := h\n      case inl =>\n        constructor\n        case left  => left; exact hP\n        case right => left; exact hP\n      case inr =>\n        constructor\n        case left  => right; exact hQ\n        case right => right; exact hR\n    case mpr =>\n      intro h\n      obtain ⟨hP | hQ, hP | hR⟩ := h\n      case inl.inl => left; exact hP\n      case inl.inr => left; exact hP\n      case inr.inl => left; exact hP\n      case inr.inr => right; exact ⟨hQ, hR⟩\ntheorem or_distributes_over_and (P Q R : Prop) :\n    P ∨ (Q ∧ R) ↔ (P ∨ Q) ∧ (P ∨ R) := by\n  sorry\ntheorem or_distributes_over_and (P Q R : Prop) :\n    P ∨ (Q ∧ R) ↔ (P ∨ Q) ∧ (P ∨ R) := by\n  sorry\n\n\ntheorem mul_eq_0 (n m : Nat) :\n    n * m = 0 ↔ n = 0 ∨ m = 0 := by\n  constructor\n  case mp => apply mul_is_zero\n  case mpr => apply factor_is_zero\ntheorem mul_eq_0 (n m : Nat) :\n    n * m = 0 ↔ n = 0 ∨ m = 0 := by\n  constructor\n  case mp => apply mul_is_zero\n  case mpr => apply factor_is_zero\ntheorem mul_eq_0 (n m : Nat) :\n    n * m = 0 ↔ n = 0 ∨ m = 0 := by\n  constructor\n  case mp => apply mul_is_zero\n  case mpr => apply factor_is_zero\n\n\n","context":"Logical Foundations\u0009Logic in Lean\u0009Truth","header":"8.3.1. Logical Equivalence","id":"/Logic/#Logical-Foundations--Logic-in-Lean--Truth--Logical-Equivalence"}});